 "decisions": [
  {
   "title": "Data migrates to the target PostgreSQL database",
   "context": "The target keeps its data in PostgreSQL, so it cannot use the legacy engine's driver, its qualified table names (db_pagos, db_admin, db_cuentas) or call its stored procedures.",
   "decision": "Use data_strategy migration: the four legacy tables (pg_orden, ad_tarifa_empresa, ad_servicio, ct_cuenta) move to the target database as payment_order, company_tariff, payment_service and account, with the legacy columns kept in snake_case and the legacy precision. The legacy procedure db_cuentas..sp_debito is not called: DebitGateway is implemented in the target against the migrated account data.",
   "consequences": "A data migration with reconciliation of the four tables is required. The balance update and movement sequence logic of sp_debito is not part of the approved rules or the inventory, so its behaviour (including the failure conditions and the generation of the movement sequence) must be specified and confirmed at C3 and proven by replaying the golden master. Other systems that still use the legacy tables or sp_debito must be synchronised or migrated in coordination."
  },
  {
   "title": "Single transaction from the first debit to the order update",
   "context": "The legacy opens the transaction at line 108 after all validations, and rolls back at three points (lines 119, 136, 155), committing at line 161.",
   "decision": "The PayOrder use case is one unit of work in the target database: validations and calculations run before it begins, and the debit, optional commission debit and order update run inside. Any failure rolls back everything and rejects with the matching error code: DEBIT_FAILED, COMMISSION_FAILED or ORDER_UPDATE_FAILED. There are no savepoints.",
   "consequences": "Since account and order data now live in the same database, the debit and the order update share one local transaction. A debit is never kept if the commission or the order update fails. Rejections before the transaction do not roll back anything because nothing has been written yet."
  },
  {
   "title": "Failure of the debit mapped by the gateway",
   "context": "The legacy treats a non-zero return code of sp_debito (or @@error) as a failure, and reads the movement sequence from the output parameter @o_secuencial.",
   "decision": "DebitGateway.debit returns the movement sequence and raises a failure when the debit cannot be done. The use case maps that failure to DEBIT_FAILED for the order debit and to COMMISSION_FAILED for the separate commission debit. The commission call ignores the returned sequence.",
   "consequences": "Return-code plumbing is not translated. Exceptions replace it."
  },
  {
   "title": "Validation order and early rejection preserved",
   "context": "The legacy evaluates account type, order existence, order status, tariff, commission, total and funds in that order, and the first failing check wins.",
   "decision": "The use case keeps the same order of checks, so the same error is produced for the same input.",
   "consequences": "Error precedence is identical to the legacy."
  },
  {
   "title": "Monetary arithmetic and rounding",
   "context": "The legacy computes with money (4 decimals) and uses round(@w_tarifa / 2, 2) for the WEB channel.",
   "decision": "Use BigDecimal with scale 4 for amounts (numeric(19,4) in PostgreSQL). The WEB commission is the tariff divided by 2 and rounded to 2 decimals with HALF_UP, then stored with scale 4. A NULL tariff becomes 0, and the NOMINA service always yields commission 0.",
   "consequences": "Results match the legacy for amounts with up to 4 decimals. The separate-charge flag is 'N' when the tariff comes from the service default."
  },
  {
   "title": "Missing account row behaves as in the legacy",
   "context": "If the balance lookup returns no row, @w_saldo stays NULL and the funds comparison is not true, so the legacy does not reject with 50004 and goes on to the debit.",
   "decision": "An empty result from AccountRepository is treated as an unknown balance: the funds check does not reject, and the debit is attempted, where DebitGateway decides.",
   "consequences": "This legacy behaviour is kept on purpose. The reviewer may decide to reject unknown accounts in a later change."
  },
  {
   "title": "Channel default and error logging",
   "context": "@i_canal defaults to 'WEB' in the legacy, and errors are logged through cobis..sp_cerror.",
   "decision": "If the channel is not provided, the use case uses 'WEB'. cobis..sp_cerror is infrastructure and is not translated: the error code and message are returned by the HTTP layer and logged by the framework.",
   "consequences": "No call to sp_cerror from the new service."
  }
 ],
 "masks": [],
 "infrastructure": [
  "cobis..sp_cerror"
 ],
 "data_strategy": "migration"
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Account type must be CTE, AHO or VIR",
  "category": "validation",
  "priority": "P0",
  "statement": "A payment order is only accepted for account types CTE, AHO or VIR. Any other account type is rejected with error 50001 and the message 'TIPO DE CUENTA NO PERMITIDO'.",
  "condition": "@i_tipo_cuenta not in ('CTE', 'AHO', 'VIR')",
  "action": "Set @w_error = 50001 and @o_mensaje = 'TIPO DE CUENTA NO PERMITIDO'.",
  "inputs": [
   {
    "name": "@i_tipo_cuenta",
    "type": "text(fixed,3,iso8859-1)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "@w_error",
    "type": "integer(32,signed)",
    "description": ""
   },
   {
    "name": "@o_mensaje",
    "type": "text(var,120,iso8859-1)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account type is allowed\n  Given the account type is 'AHO'\n  When the payment order is validated\n  Then no error is set for the account type",
   "Scenario: Account type is not allowed\n  Given the account type is 'PRE'\n  When the payment order is validated\n  Then the error code is 50001\n  And the message is 'TIPO DE CUENTA NO PERMITIDO'"
  ],
  "sources": [
   {
    "file": "sp/sp_pago_orden.sp",
    "line_start": 34,
    "line_end": 37
   }
  ]
 },
 {
