package com.bank.payments.domain.error;

/** A business rejection with its stable code and the code the legacy returned. */
public class BusinessError extends RuntimeException {

    private final String code;
    private final String legacyCode;

    public BusinessError(String code, String legacyCode, String message) {
        super(message);
        this.code = code;
        this.legacyCode = legacyCode;
    }

    public String code() {
        return code;
    }

    public String legacyCode() {
        return legacyCode;
    }
}


