                log.add("tariff:" + empresa + "/" + servicio);
                return tariff;
            };
            ServiceRepository services = servicio -> {
                log.add("service:" + servicio);
                return service;
            };
            AccountRepository accounts = (cuenta, tipoCuenta) -> {
                log.add("account:" + cuenta + "/" + tipoCuenta);
                return account;
            };
            DebitGateway gateway = (cuenta, tipoCuenta, valor, referencia) -> {
                int index = debits.size();
                log.add("debit");
                debits.add(new DebitCall(cuenta, tipoCuenta, valor, referencia));
                if (index == 0 && firstDebitFailure != null) {
                    throw firstDebitFailure;
                }
                if (index == 1 && secondDebitFailure != null) {
                    throw secondDebitFailure;
                }
                return sequences[Math.min(index, sequences.length - 1)];
            };
            return new PayOrderService(orders, tariffs, services, accounts, gateway);
        }
    }

    private static BigDecimal bd(String value) {
        return value == null ? null : new BigDecimal(value);
    }

    private static PayOrderRequest request(String servicio, String tipoCuenta, String valor, String canal) {
        return new PayOrderRequest(100, 1, servicio, tipoCuenta, "1234567890", bd(valor), canal, PROCESS_DATE);
    }

    private static CompanyTariff companyTariff(String servicio, String valor, String separada) {
        return new CompanyTariff(1, servicio, bd(valor), separada);
    }

    private static Account account(String tipo, String saldo) {
        return new Account("1234567890", tipo, bd(saldo));
    }

    private static void assertBusinessError(ThrowingCallable callable, String legacyCode, String code, String message) {
        Throwable thrown = catchThrowable(callable);
        assertThat(thrown).isInstanceOf(BusinessError.class);
        BusinessError error = (BusinessError) thrown;
        assertThat(error.legacyCode()).isEqualTo(legacyCode);
        assertThat(error.code()).isEqualTo(code);
        assertThat(error.getMessage()).isEqualTo(message);
    }

